final Stopwatch _bootSw = Stopwatch()..start();

Future<void> _runSmokeTest(PlaybackController controller) async {
  // Smoke test: scan library and drive playback using fixed media fixtures.
  const mediaRoot = '/opt/nothingness/media';
  try {
    final lib = LibraryService();
    await lib.addRoot(mediaRoot);
    final tracks = await controller.scanFolder(mediaRoot);
    if (tracks.isNotEmpty) {
      await controller.setQueue(tracks, startIndex: 0);
      await controller.playPause();
      await Future.delayed(const Duration(seconds: 1));
      await controller.next();
      await Future.delayed(const Duration(seconds: 1));
      await controller.seek(const Duration(seconds: 30));
      await Future.delayed(const Duration(seconds: 1));
      await controller.playPause();
    }
  } catch (e, st) {
    debugPrint('[smoke] error: $e $st');
  }
}

